insert into public.documents (id, title, grade_id, subject_id, textbook_series_id, chapter_id, lesson_id, type, description, file_path, file_size, page_count, source, license_note, status, created_at, updated_at, published_at) values
  ('f992ac49-8659-5e1f-bba7-91867c72a7af', 'Công thức nguyên hàm cơ bản – Toán 12', 12, 'toan', 'ket-noi', '77ec3165-deb2-56cb-b7ad-b53a2bbb63bd', 'bbecb97b-aa77-5ba9-9d6a-9e500195de96', 'tom_tat', 'Bảng nguyên hàm của các hàm số thường gặp, tính chất và ví dụ áp dụng nhanh.', 'samples/toan12-nguyen-ham-cong-thuc.pdf', 50257, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-12T01:00:00.000Z', '2026-11-12T02:00:00.000Z', '2026-11-12T02:00:00.000Z'),
  ('d9585504-f74f-570c-b4d0-2bc5601e727c', 'Tích phân: lý thuyết và ví dụ minh họa', 12, 'toan', 'ket-noi', '77ec3165-deb2-56cb-b7ad-b53a2bbb63bd', 'faff6b82-8308-5af1-9abc-6b2dfaeb15a3', 'ly_thuyet', 'Định nghĩa tích phân, các tính chất cơ bản và ứng dụng tính diện tích hình phẳng.', 'samples/toan12-tich-phan-ly-thuyet.pdf', 50082, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-12T01:00:00.000Z', '2026-11-12T02:00:00.000Z', '2026-11-12T02:00:00.000Z'),
  ('9885f80c-6573-5fd8-b301-5f960bf20c76', 'Đề ôn tập chương Nguyên hàm – Tích phân', 12, 'toan', 'ket-noi', '77ec3165-deb2-56cb-b7ad-b53a2bbb63bd', 'faff6b82-8308-5af1-9abc-6b2dfaeb15a3', 'de_kiem_tra', '5 câu tự luận có đáp án chi tiết để tự kiểm tra cuối chương.', 'samples/toan12-on-tap-nguyen-ham-tich-phan.pdf', 49043, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-14T01:00:00.000Z', '2026-11-14T02:00:00.000Z', '2026-11-14T02:00:00.000Z'),
  ('82ee60f3-3a1b-5c19-b500-6a95a0b26536', 'Bài tập tính đơn điệu và cực trị có lời giải', 12, 'toan', 'ket-noi', '702fc057-2edc-5255-a3fd-542fdf7e7009', '4855e2ae-fe50-55c9-87d1-77ecd5a2d4e4', 'bai_tap', 'Các bài tập xét chiều biến thiên và tìm cực trị của hàm bậc ba, bậc bốn trùng phương.', 'samples/toan12-don-dieu-cuc-tri.pdf', 50147, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-08T01:00:00.000Z', '2026-11-08T02:00:00.000Z', '2026-11-08T02:00:00.000Z'),
  ('9ad7e77b-0036-5fea-82d6-aa06f51009f5', 'Mệnh đề và tập hợp – Tóm tắt lý thuyết', 10, 'toan', 'ket-noi', '44f02f68-d1c0-5d33-b3d8-e05ab0a450ea', '6c9cea22-bf7d-5a0f-9598-630cdf0b310c', 'tom_tat', 'Mệnh đề, phủ định, mệnh đề kéo theo; tập hợp và các phép toán giao, hợp, hiệu.', 'samples/toan10-menh-de-tap-hop.pdf', 52226, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-05T01:00:00.000Z', '2026-11-05T02:00:00.000Z', '2026-11-05T02:00:00.000Z'),
  ('16ee3ab2-b894-5c7a-80a7-1a1a67832444', 'Hàm số bậc hai – Bài tập có lời giải', 10, 'toan', 'ket-noi', '52c61fca-8303-5b8f-af37-2fd5c8bea246', '457ddae0-788d-5f52-a5aa-c060ed9914b3', 'bai_tap', 'Xác định đỉnh, trục đối xứng, chiều biến thiên và tìm parabol qua hai điểm.', 'samples/toan10-ham-so-bac-hai.pdf', 53584, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-06T01:00:00.000Z', '2026-11-06T02:00:00.000Z', '2026-11-06T02:00:00.000Z'),
  ('f7595ebb-ae20-50da-a3c4-18b75809bb6a', 'Phương trình lượng giác cơ bản – Công thức nghiệm', 11, 'toan', 'ket-noi', '1f7f941f-9981-51b2-814f-4b16b83aeb12', 'f62acbda-3037-5dbc-9f7a-1564e8f10ed7', 'tom_tat', 'Công thức nghiệm của sin x = a, cos x = a, tan x = a, cot x = a và các trường hợp đặc biệt.', 'samples/toan11-pt-luong-giac.pdf', 48802, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-09T01:00:00.000Z', '2026-11-09T02:00:00.000Z', '2026-11-09T02:00:00.000Z'),
  ('5b28282b-90db-51a4-b38d-50313e8ef48d', 'Chuyển động thẳng biến đổi đều – Công thức', 10, 'vat-ly', 'ket-noi', 'bc13dedc-4c03-59fb-a001-45fed5fa70e1', '5f7214d8-f5c2-5b24-996e-363eac3aafab', 'tom_tat', 'Gia tốc, vận tốc, độ dịch chuyển và hệ thức độc lập thời gian, kèm ví dụ.', 'samples/ly10-bien-doi-deu.pdf', 49264, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-10T01:00:00.000Z', '2026-11-10T02:00:00.000Z', '2026-11-10T02:00:00.000Z'),
  ('8e777d57-219c-5312-a212-4014080898c7', 'Dao động điều hòa – Lý thuyết trọng tâm', 11, 'vat-ly', 'ket-noi', 'f8571566-65d5-5302-864e-47c71921ecb6', 'a5bfe23a-55e4-571b-81a0-c9221cc2e756', 'ly_thuyet', 'Phương trình li độ, vận tốc, gia tốc; chu kì, tần số và các giá trị cực đại.', 'samples/ly11-dao-dong-dieu-hoa.pdf', 50213, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-11T01:00:00.000Z', '2026-11-11T02:00:00.000Z', '2026-11-11T02:00:00.000Z'),
  ('b98bc2bc-2100-57d3-9721-5aa603d40e75', 'Cấu trúc của chất – Câu hỏi ôn tập', 12, 'vat-ly', 'ket-noi', 'fcda9351-13b7-5e7f-aac2-b2c8970cb728', '1842c275-cbd3-5ecc-bb50-ef6e7362f0c5', 'de_kiem_tra', 'Câu hỏi ôn tập mô hình động học phân tử và sự chuyển thể (đang chờ duyệt).', 'samples/ly12-cau-truc-chat.pdf', 45601, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'pending', '2026-11-16T01:00:00.000Z', '2026-11-16T02:00:00.000Z', null),
  ('44fa80f7-2544-5776-91b3-4cf564f83496', 'Cấu tạo nguyên tử – Tóm tắt', 10, 'hoa-hoc', 'ket-noi', '576872e7-5ed1-57ff-b2bc-e32073865919', 'cb24688c-913d-5bf2-8ad5-8ab7d186ef14', 'tom_tat', 'Thành phần nguyên tử, số khối, đồng vị, nguyên tử khối trung bình và cấu hình electron.', 'samples/hoa10-cau-tao-nguyen-tu.pdf', 51161, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-07T01:00:00.000Z', '2026-11-07T02:00:00.000Z', '2026-11-07T02:00:00.000Z'),
  ('02d9aecf-c8c2-5e57-b7ee-94372ca97bac', 'pH của dung dịch – Bài tập có lời giải', 11, 'hoa-hoc', 'ket-noi', '996c5863-75ba-5443-9d03-231adae376b1', '7beda0d2-601d-52e3-8aba-0933ba28ab3c', 'bai_tap', 'Tính pH của dung dịch acid mạnh, base mạnh và nhận biết môi trường.', 'samples/hoa11-ph-bai-tap.pdf', 48431, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-13T01:00:00.000Z', '2026-11-13T02:00:00.000Z', '2026-11-13T02:00:00.000Z'),
  ('53240ff8-64e3-50ad-93d4-c11dc904c24e', 'Ester – Lipid: Sơ đồ tư duy', 12, 'hoa-hoc', 'ket-noi', 'b96ca31a-212c-5e85-9729-479eb6985554', 'c9924dcd-c72e-5b05-a797-3ce55fd90e69', 'tom_tat', 'Bản nháp, chưa có tệp đính kèm.', null, null, null, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'draft', '2026-11-16T01:00:00.000Z', '2026-11-16T02:00:00.000Z', null),
  ('6a22b213-2b88-5e52-b47d-c92c364a88cf', 'Thì hiện tại hoàn thành và quá khứ đơn', 11, 'tieng-anh', null, 'ae75bf40-cb28-5cb4-8db0-ec5318b42536', 'd5bd286f-556f-533c-9dbe-5673602c2f2e', 'tom_tat', 'Cấu trúc, cách dùng, dấu hiệu nhận biết và cách phân biệt hai thì dễ nhầm lẫn.', 'samples/anh11-cac-thi.pdf', 51136, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-04T01:00:00.000Z', '2026-11-04T02:00:00.000Z', '2026-11-04T02:00:00.000Z'),
  ('586ec359-817d-5964-ab85-71c822e0c47b', 'Câu bị động – Lý thuyết và bài tập', 12, 'tieng-anh', null, 'c0b76259-0f33-5c82-9f6a-bae3a2688d86', 'e3212169-aa17-5ebe-850c-4be2704c8a12', 'bai_tap', 'Công thức bị động theo từng thì, động từ khuyết thiếu và bài tập chuyển câu có đáp án.', 'samples/anh12-bi-dong.pdf', 50623, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-03T01:00:00.000Z', '2026-11-03T02:00:00.000Z', '2026-11-03T02:00:00.000Z'),
  ('4c46bd65-61ec-5a3b-9535-3d61ff1607b2', 'Đặc trưng thể loại thần thoại', 10, 'ngu-van', 'ket-noi', '07e25c84-191b-5bad-8bfe-87501e6694d1', '8b64c522-6889-5a31-81db-2d354a3fbc04', 'ly_thuyet', 'Không gian, thời gian, nhân vật, cốt truyện của thần thoại và hướng dẫn đọc hiểu.', 'samples/van10-than-thoai.pdf', 47502, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-02T01:00:00.000Z', '2026-11-02T02:00:00.000Z', '2026-11-02T02:00:00.000Z'),
  ('4a7b1aed-a9f9-55e8-ab5b-a19adb3aa715', 'Cách làm bài nghị luận xã hội', 12, 'ngu-van', null, '3f6c6a13-b4ea-5e3a-bb30-cb8d646ea36a', '8efea40b-3f76-559f-91ca-0557e18ed8a3', 'ly_thuyet', 'Dàn ý chung, các bước triển khai luận điểm và lỗi thường gặp khi viết bài.', 'samples/van12-nlxh.pdf', 48390, 1, 'Nhóm StudyHub biên soạn', 'Tự biên soạn — chia sẻ miễn phí cho mục đích học tập', 'published', '2026-11-01T01:00:00.000Z', '2026-11-01T02:00:00.000Z', '2026-11-01T02:00:00.000Z')
insert into public.quizzes (id, title, description, grade_id, subject_id, chapter_id, duration_minutes, is_published, created_at, updated_at) values
  ('dd70de99-b3c9-5d2e-8517-9d063f5e8d14', 'Nguyên hàm cơ bản', '6 câu kiểm tra bảng nguyên hàm và cách tìm nguyên hàm thỏa điều kiện.', 12, 'toan', '77ec3165-deb2-56cb-b7ad-b53a2bbb63bd', 10, true, '2026-11-15T01:00:00.000Z', '2026-11-15T01:00:00.000Z'),
  ('d52c3b1c-d6a7-59ed-89bd-6524977b0475', 'Mệnh đề và tập hợp', '5 câu nhận biết mệnh đề, phủ định và phép toán trên tập hợp.', 10, 'toan', '44f02f68-d1c0-5d33-b3d8-e05ab0a450ea', 8, true, '2026-11-15T01:00:00.000Z', '2026-11-15T01:00:00.000Z'),
  ('28369309-ac75-5af5-a2e6-21250752e345', 'Chuyển động thẳng biến đổi đều', '6 câu vận dụng công thức vận tốc, độ dịch chuyển và hệ thức độc lập.', 10, 'vat-ly', 'bc13dedc-4c03-59fb-a001-45fed5fa70e1', 12, true, '2026-11-15T01:00:00.000Z', '2026-11-15T01:00:00.000Z'),
  ('1e3067ae-5f18-5926-9a9a-9958758c8c50', 'Cấu tạo nguyên tử', '5 câu về thành phần nguyên tử, số khối, đồng vị và cấu hình electron.', 10, 'hoa-hoc', '576872e7-5ed1-57ff-b2bc-e32073865919', 8, true, '2026-11-15T01:00:00.000Z', '2026-11-15T01:00:00.000Z'),
  ('cb70ad29-e2f8-58be-868d-edb8ce22a48b', 'Present perfect vs Past simple', '5 câu chọn thì đúng dựa vào dấu hiệu thời gian.', 11, 'tieng-anh', 'ae75bf40-cb28-5cb4-8db0-ec5318b42536', 6, true, '2026-11-15T01:00:00.000Z', '2026-11-15T01:00:00.000Z'),
  ('2c4c61d5-4a2b-5f93-b642-094808a44d13', 'pH của dung dịch (bản nháp)', 'Đề đang soạn — chưa xuất bản.', 11, 'hoa-hoc', '996c5863-75ba-5443-9d03-231adae376b1', 5, false, '2026-11-15T01:00:00.000Z', '2026-11-15T01:00:00.000Z')
insert into public.questions (id, quiz_id, text, explanation, sort_order) values
  ('14bc68b4-321a-5adb-a08b-eb063783bf5e', 'dd70de99-b3c9-5d2e-8517-9d063f5e8d14', 'Họ nguyên hàm của hàm số f(x) = x³ là:', 'Áp dụng ∫xⁿ dx = xⁿ⁺¹/(n+1) + C với n = 3, ta được x⁴/4 + C.', 1),
  ('54c0e56f-17ea-558d-89d6-a8d2347db113', 'dd70de99-b3c9-5d2e-8517-9d063f5e8d14', '∫ eˣ dx bằng:', 'Đạo hàm của eˣ là chính nó, nên ∫ eˣ dx = eˣ + C.', 2),
  ('3eb06a15-102e-5d46-ae45-02f4c5eeb167', 'dd70de99-b3c9-5d2e-8517-9d063f5e8d14', 'Với x ≠ 0, ∫ (1/x) dx bằng:', '(ln|x|)'' = 1/x với mọi x ≠ 0, nên ∫ (1/x) dx = ln|x| + C.', 3),
  ('7128bf53-c754-5ee4-a1a5-921d95cde0fd', 'dd70de99-b3c9-5d2e-8517-9d063f5e8d14', '∫ cos x dx bằng:', '(sin x)'' = cos x, nên ∫ cos x dx = sin x + C.', 4),
  ('56623704-b77c-591f-b24d-7cfed936768c', 'dd70de99-b3c9-5d2e-8517-9d063f5e8d14', 'Biết F(x) là một nguyên hàm của f(x) = 2x và F(1) = 3. Khi đó F(x) là:', 'F(x) = x² + C. Từ F(1) = 1 + C = 3 suy ra C = 2, vậy F(x) = x² + 2.', 5),
  ('ed074f26-cbad-587c-ae28-b58ab1d0c152', 'dd70de99-b3c9-5d2e-8517-9d063f5e8d14', '∫ (2x + 1) dx bằng:', '∫ 2x dx = x² và ∫ 1 dx = x, cộng lại được x² + x + C.', 6),
  ('9cf2d26a-37ed-5ad6-89cf-17731177e07d', 'd52c3b1c-d6a7-59ed-89bd-6524977b0475', 'Câu nào sau đây là một mệnh đề?', 'Mệnh đề là câu khẳng định có tính đúng hoặc sai xác định. Câu cảm thán, câu hỏi và câu chứa biến chưa xác định giá trị không phải mệnh đề.', 1),
  ('3d421fb0-3369-5843-a884-e4f159a1cdd7', 'd52c3b1c-d6a7-59ed-89bd-6524977b0475', 'Phủ định của mệnh đề “∀x ∈ ℝ, x² ≥ 0” là:', 'Phủ định của “∀x, P(x)” là “∃x, P(x) sai”. Phủ định của x² ≥ 0 là x² < 0.', 2),
  ('0da66d5c-7a70-5bbc-b49f-87b80659a09b', 'd52c3b1c-d6a7-59ed-89bd-6524977b0475', 'Cho A = {1; 2; 3; 4} và B = {3; 4; 5}. Tập A ∩ B là:', 'A ∩ B gồm các phần tử vừa thuộc A vừa thuộc B: 3 và 4.', 3),
  ('52d84355-005d-53d1-a235-bb35d91c637c', 'd52c3b1c-d6a7-59ed-89bd-6524977b0475', 'Với A, B như câu trên, tập A \ B là:', 'A \ B gồm các phần tử thuộc A nhưng không thuộc B: 1 và 2.', 4),
  ('2c639691-9eb0-5b82-933e-3bce3daefe9d', 'd52c3b1c-d6a7-59ed-89bd-6524977b0475', 'Tập {a; b; c} có bao nhiêu tập con?', 'Tập có n phần tử có 2ⁿ tập con. Với n = 3: 2³ = 8 (kể cả ∅ và chính nó).', 5),
  ('977b0622-4a22-5fa5-ada7-1923209853e8', '28369309-ac75-5af5-a2e6-21250752e345', 'Công thức vận tốc của chuyển động thẳng biến đổi đều là:', 'Từ a = Δv/Δt suy ra v = v₀ + at.', 1),
  ('9ae9491a-73e6-56a3-bc2c-d34b3ef315bc', '28369309-ac75-5af5-a2e6-21250752e345', 'Một xe bắt đầu chuyển động nhanh dần đều với gia tốc 2 m/s². Vận tốc của xe sau 5 s là:', 'v₀ = 0, v = at = 2 · 5 = 10 m/s.', 2),
  ('3de46d83-7a07-58f6-963e-1349bf9c0d4a', '28369309-ac75-5af5-a2e6-21250752e345', 'Quãng đường xe ở câu trên đi được trong 5 s đầu là:', 'd = v₀t + at²/2 = 0 + 2 · 5²/2 = 25 m.', 3),
  ('325f64be-ed9f-52a5-87ee-97eef49b9692', '28369309-ac75-5af5-a2e6-21250752e345', 'Trong chuyển động thẳng chậm dần đều thì:', 'Chậm dần đều nghĩa là độ lớn vận tốc giảm đều, khi đó vectơ gia tốc ngược chiều vectơ vận tốc (a·v < 0).', 4),
  ('25f360dc-2cf5-586b-973b-e22898220c4c', '28369309-ac75-5af5-a2e6-21250752e345', 'Ô tô đang chạy 20 m/s thì hãm phanh, chuyển động chậm dần đều với gia tốc có độ lớn 4 m/s². Thời gian đến khi dừng là:', '0 = 20 − 4t ⇒ t = 5 s.', 5),
  ('9ac24a24-2f18-59c8-a919-6754c49d51bc', '28369309-ac75-5af5-a2e6-21250752e345', 'Hệ thức liên hệ giữa vận tốc, gia tốc và độ dịch chuyển (không chứa t) là:', 'Khử t từ v = v₀ + at và d = v₀t + at²/2 ta được v² − v₀² = 2ad.', 6),
  ('d903d16a-e324-54b1-b448-fa01fb4cb69c', '1e3067ae-5f18-5926-9a9a-9958758c8c50', 'Hạt mang điện tích dương trong hạt nhân nguyên tử là:', 'Hạt nhân gồm proton (điện tích +1) và neutron (không mang điện). Electron ở lớp vỏ, mang điện −1.', 1),
  ('06882233-1efb-5f68-9c03-272c87681571', '1e3067ae-5f18-5926-9a9a-9958758c8c50', 'Nguyên tử có Z = 11 thì có bao nhiêu electron?', 'Nguyên tử trung hòa điện: số electron = số proton = Z = 11.', 2),
  ('20048fe4-6576-5c25-a0c5-a48a49277426', '1e3067ae-5f18-5926-9a9a-9958758c8c50', 'Nguyên tử sodium có Z = 11 và số khối A = 23. Số neutron là:', 'N = A − Z = 23 − 11 = 12.', 3),
  ('6ae98100-57fb-5ed9-bf0a-dfc268886be2', '1e3067ae-5f18-5926-9a9a-9958758c8c50', 'Cấu hình electron của nguyên tử oxygen (Z = 8) là:', 'Điền 8 electron theo thứ tự 1s → 2s → 2p: 1s² 2s² 2p⁴.', 4),
  ('80ebcf67-a0f6-577c-aae9-4e49ab2b4971', '1e3067ae-5f18-5926-9a9a-9958758c8c50', 'Đồng vị là những nguyên tử có cùng:', 'Các đồng vị của một nguyên tố có cùng Z (số proton), khác N nên khác số khối A.', 5),
  ('37000c8b-9f45-5b08-a30c-3d8a53041e4b', 'cb70ad29-e2f8-58be-868d-edb8ce22a48b', 'She ___ in Hanoi since 2018.', '“since + mốc thời gian” diễn tả hành động bắt đầu trong quá khứ và kéo dài đến hiện tại → hiện tại hoàn thành: has lived.', 1),
  ('7f08dc0b-752c-5c92-8fb7-c623c708dee2', 'cb70ad29-e2f8-58be-868d-edb8ce22a48b', 'I ___ my homework yesterday.', '“yesterday” là thời điểm xác định trong quá khứ → quá khứ đơn: did.', 2),
  ('c76a5d21-92f9-59e8-a5d9-6140a886fbff', 'cb70ad29-e2f8-58be-868d-edb8ce22a48b', '___ you ever ___ to Da Lat?', '“ever” hỏi về trải nghiệm tính đến hiện tại → Have you ever been to…?', 3),
  ('6ef1789b-733a-5e52-84ab-386da159a9ac', 'cb70ad29-e2f8-58be-868d-edb8ce22a48b', 'They ___ the project two days ago.', '“ago” đi với quá khứ đơn: finished.', 4),
  ('db3dc4c0-4394-5e5a-8be0-04e1da8fdba4', 'cb70ad29-e2f8-58be-868d-edb8ce22a48b', 'We ___ each other for ten years, and we are still best friends.', '“for ten years” + vẫn còn đúng ở hiện tại → hiện tại hoàn thành. “know” là động từ trạng thái nên không dùng dạng tiếp diễn.', 5),
  ('c5836878-9458-53f5-8e9b-809822ca19e7', '2c4c61d5-4a2b-5f93-b642-094808a44d13', 'Dung dịch HCl 0,01 M có pH bằng:', 'HCl là acid mạnh nên [H⁺] = 0,01 = 10⁻² M ⇒ pH = −lg[H⁺] = 2.', 1),
  ('e67ff930-2df7-518d-b1a1-d6c8e4cfdfc3', '2c4c61d5-4a2b-5f93-b642-094808a44d13', 'Dung dịch có pH = 9 có môi trường:', 'Ở 25 °C, pH > 7 là môi trường base.', 2)
